mapper.select:
WITH RECURSIVE category_path AS ( SELECT category_id, parent_id FROM t_commodity_category WHERE category_id = #{categoryId}
UNION ALL
SELECT parent.category_id, parent.parent_id FROM t_commodity_category parent INNER JOIN category_path child ON child.parent_id = parent.category_id WHERE child.parent_id != 0 ) SELECT category.category_id, category.parent_id, category.status, category.is_deleted FROM t_commodity_category category INNER JOIN category_path path ON path.category_id = category.category_id ORDER BY category.category_id ASC FOR SHARE
